{
  "name": "@ghilteras/opencode-model-fallback",
  "version": "0.4.2",
  "description": "Model fallback plugin for opencode 1.18+ \u2014 maintained successor to @razroo/opencode-model-fallback (dormant since 2026-04-16). Fallback only on non-transient errors; per-session stickiness; 402 non-retryable; prose-never-error.",
  "private": false,
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "files": [
    "dist/"
  ],
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Ghilteras/opencode-model-fallback.git"
  },
  "scripts": {
    "build": "bun run build.ts",
    "typecheck": "tsc --noEmit",
    "test": "bun test"
  },
  "keywords": [
    "opencode",
    "plugin",
    "fallback",
    "model",
    "ai"
  ],
  "license": "MIT",
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.1.19",
    "@opencode-ai/sdk": ">=1.1.0"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/sdk": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.18",
    "bun-types": "1.3.6",
    "typescript": "^5.7.3"
  },
  "dependencies": {
    "jsonc-parser": "^3.3.1"
  }
}
